import json,pathlib,copy
root=pathlib.Path('/tmp/igr-hp-breakthrough'); entries=json.loads((root/'application-commands.json').read_text()); new=[]
def make(base,name,nx=None,p=None,dt=None,shift=None,rtol=None,pc=None):
 a=copy.deepcopy(next(x for x in entries if x['name']==base)); a['name']=name
 cmd=a['command']; cmd[cmd.index('--output-dir')+1]=str(root/name)
 if nx is not None:
  a['c_alpha']*= (nx/a['nx'])**2; a['nx']=nx
  cmd[cmd.index('--c-alpha')+1]=str(a['c_alpha'])
  if '--mesh' in cmd: cmd[cmd.index('--mesh')+1]=str(root/f'planar-nx{nx}.mesh')
  else:cmd+=['--mesh',str(root/f'planar-nx{nx}.mesh')]
 if dt is not None:a['dt']=dt;cmd[cmd.index('--dt')+1]=str(dt)
 if shift is not None:a['shock_x']=shift;cmd+=['--shock-x',str(shift)]
 cmd+=['--shock-width','1.25']
 if rtol is not None:cmd[cmd.index('--linear-rtol')+1]=str(rtol)
 if pc in ['chebyshev','patch0-fp64','patch0-fp32']:
  for k in ['--dense-inverse','--dense-setup']:
   i=cmd.index(k);del cmd[i:i+2]
  if pc=='chebyshev':cmd+=['--cheb-order','2','--cheb-power-iterations','3']
  else:cmd+=['--linear-solver','fgmres','--patch-radius','0','--patch-precision',pc.split('-')[1]]
 cmd[cmd.index('--timeout')+1]='240'
 new.append(a)
make('app-s0-p4-nx64','app-s0-p4-nx128',nx=128,dt=.0125)
make('app-s4-p4-nx64','app-s4-p4-nx128',nx=128,dt=.00625)
make('app-s4-p3-nx32','app-s4-p3-nx32-halfdt',dt=.0125)
for pc in ['dense','chebyshev','patch0-fp64','patch0-fp32']:
 make('app-s4-p3-nx32','app-s4-p3-nx32-loose-'+pc,rtol=1e-3,pc=pc)
for s in [2,4]:
 for p,nx in [(3,32),(4,64)]:
  make(f'app-s{s}-p{p}-nx{nx}',f'app-s{s}-p{p}-nx{nx}-shift037',shift=.4625)
(root/'application-followup-commands.json').write_text(json.dumps(new,indent=2)+'\n')
(root/'application-commands.json').write_text(json.dumps(entries+new,indent=2)+'\n')

import json,sys,pathlib,numpy as np
