import compare_dgsem_physical_fields as p
rows=json.loads((root/'application-analysis.json').read_text())['runs']; by={v['name']:v for v in rows}
def load(name,t=6):
 v=by[name]; paths=list((root/name/'vtk').rglob('*.pvd')); frame=p.select_frame(paths[0],t,1e-12)
 return p.load_mesh(pathlib.Path(frame['file']),v['p'])
base='app-s4-p3-nx32'; report={'same_grid_controls':[]}
for v in rows:
 if v['s_at_p3']==4 and v['p']==3 and v['nx']==32 and v.get('shock_x',0)==0 and v['name']!=base:
  report['same_grid_controls'].append({'reference':base,'candidate':v['name'],'comparison':p.compare(load(base),load(v['name']),24,6)})
a,b=load(base,0),load(base+'-halfdt',0)
report['explicit_width_default_control']={'reference':base,'candidate':base+'-halfdt','same_initial_coefficients':bool(np.array_equal(a['values'],b['values'])),'max_initial_field_difference':float(np.max(abs(a['values']-b['values'])))}
report['reference_refinement']=[{'reference':'app-s0-p4-nx128','candidate':'app-s0-p4-nx64','comparison':p.compare(load('app-s0-p4-nx128'),load('app-s0-p4-nx64'),24,6)}, {'reference':'app-s4-p4-nx128','candidate':'app-s4-p4-nx64','comparison':p.compare(load('app-s4-p4-nx128'),load('app-s4-p4-nx64'),24,6)}]
(root/'application-extra-analysis.json').write_text(json.dumps(report,indent=2)+'\n')
for v in report['same_grid_controls']:
 print(v['candidate'],v['comparison']['fields']['density']['l2_relative'],v['comparison']['fields']['sigma']['l2_relative'])
print(report['explicit_width_default_control'])
report['no_volume_llf_controls']=[]
for reference,candidate in [('app-s2-p4-nx128-novolumellf','app-s2-p4-nx64-novolumellf'),('app-s2-p4-nx128-novolumellf','app-s2-p3-nx32-novolumellf'),('app-s2-p4-nx64-shift037-novolumellf','app-s2-p3-nx32-shift037-novolumellf')]:
 v={'reference':reference,'candidate':candidate,'comparison':p.compare(load(reference),load(candidate),24,6)}
 report['no_volume_llf_controls'].append(v)
 print('noLLF',candidate,v['comparison']['fields']['density']['l2_relative'],v['comparison']['fields']['sigma']['l2_relative'])
report['phase_sensitivity']=[]
for porder,nx in [(3,32),(4,64)]:
 for suffix in ['', '-novolumellf']:
  a=load(f'app-s2-p{porder}-nx{nx}'+suffix);b=load(f'app-s2-p{porder}-nx{nx}-shift037'+suffix);shift=.4625
  edges=np.unique(np.r_[a['x'],b['x']-shift,-8,8]);edges=edges[(edges>=-8)&(edges<=8)]
  z,w=np.polynomial.legendre.leggauss(6);half=np.diff(edges)/2;xq=((edges[:-1,None]+edges[1:,None])/2+half[:,None]*z).ravel();weight=(half[:,None]*w).ravel()
  av=p.evaluate(a,xq,np.zeros_like(xq));bv=p.evaluate(b,xq+shift,np.zeros_like(xq))
  errs={key:float(np.sqrt(np.dot(weight,(av[:,i]-bv[:,i])**2)/np.dot(weight,av[:,i]**2))) for i,key in [(0,'density'),(4,'sigma')]}
  report['phase_sensitivity'].append({'p':porder,'nx':nx,'volume_llf':not bool(suffix),'translation':shift,'aligned_window':[-8,8],'relative_l2':errs,'scope':'Translation sensitivity; fixed far boundaries and tiny nonzero IC tails prevent exact continuum translation equivalence.'})
  print('phase',porder,nx,suffix,errs)
(root/'application-extra-analysis.json').write_text(json.dumps(report,indent=2)+'\n')
